-- OAC hosted setup. Generated by scripts/build-hosted-sql.mjs from 17 migrations plus supabase/seed.sql.
-- Run it ONCE on an EMPTY Supabase project: dashboard, SQL Editor, New query, paste everything, Run.
-- Everything is one transaction: if any statement fails, nothing is applied.
-- Afterwards create the demo accounts with `npm run demo:hosted` (see docs/deploy.md).

begin;


-- ===================== 0001_schema.sql =====================

-- OAC pre-order: schema, helper, college-email guard.
-- All writes to profiles, orders, order_items and slots.booked_count go through
-- security-definer RPCs added in later migrations; see 0002_rls.sql for grants and policies.

create type public.user_role as enum ('student', 'staff', 'admin');
create type public.order_status as enum ('placed', 'accepted', 'ready', 'collected', 'cancelled', 'no_show');

-- ---------------------------------------------------------------------------
-- app_settings: a single row. college_email_domain is NULL until configured,
-- and the sign-up guard fails closed while it is NULL.
-- ---------------------------------------------------------------------------
create table public.app_settings (
  id boolean primary key default true check (id),
  order_cutoff_minutes int not null default 5 check (order_cutoff_minutes >= 0),
  no_show_hold_minutes int not null default 15 check (no_show_hold_minutes >= 0),
  college_email_domain text check (
    college_email_domain is null
    or (college_email_domain = lower(college_email_domain) and college_email_domain !~ '[@[:space:]]')
  )
);
insert into public.app_settings default values;

-- ---------------------------------------------------------------------------
-- profiles: one row per auth user, created by RPC (students) or the admin script.
-- Staff and admin have no phone or registration number.
-- ---------------------------------------------------------------------------
create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  full_name text not null,
  phone text,
  reg_no text unique,
  role public.user_role not null default 'student',
  is_defaulter boolean not null default false,
  is_active boolean not null default true,
  must_change_password boolean not null default false,
  created_at timestamptz not null default now(),
  constraint profiles_student_contact_required
    check (role <> 'student' or (phone is not null and reg_no is not null))
);

-- Role of the caller, or NULL when signed out, without a profile, or deactivated.
-- Always call it schema-qualified: `current_role` is also an SQL keyword.
create function public.current_role()
returns public.user_role
language sql
stable
security definer
set search_path = ''
as $$
  select p.role from public.profiles p where p.id = (select auth.uid()) and p.is_active
$$;

-- ---------------------------------------------------------------------------
-- Menu and slots
-- ---------------------------------------------------------------------------
create table public.menu_items (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  description text,
  price_paise int not null check (price_paise >= 0),
  category text not null,
  is_available boolean not null default true,
  sort int not null default 0
);

create table public.slots (
  id uuid primary key default gen_random_uuid(),
  starts_at timestamptz not null unique,
  capacity int not null check (capacity > 0),
  booked_count int not null default 0,
  constraint slots_booked_count_within_capacity check (booked_count between 0 and capacity)
);

-- ---------------------------------------------------------------------------
-- Orders
-- ---------------------------------------------------------------------------
create table public.orders (
  id uuid primary key default gen_random_uuid(),
  code text not null unique,
  student_id uuid not null references public.profiles (id),
  slot_id uuid not null references public.slots (id),
  status public.order_status not null default 'placed',
  total_paise int not null check (total_paise >= 0),
  request_id uuid not null,
  created_at timestamptz not null default now(),
  accepted_at timestamptz,
  ready_at timestamptz,
  collected_at timestamptz,
  flagged_at timestamptz,
  paid_at timestamptz,
  unique (student_id, request_id)
);

create index orders_slot_id_status_idx on public.orders (slot_id, status);
create index orders_student_id_created_at_idx on public.orders (student_id, created_at desc);
create index orders_status_created_at_idx on public.orders (status, created_at);

-- name and unit price are snapshots taken at order time.
create table public.order_items (
  order_id uuid not null references public.orders (id) on delete cascade,
  menu_item_id uuid not null references public.menu_items (id),
  name text not null,
  unit_price_paise int not null check (unit_price_paise >= 0),
  qty int not null check (qty > 0),
  primary key (order_id, menu_item_id)
);

create table public.push_subscriptions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  endpoint text not null unique,
  p256dh text not null,
  auth text not null
);
create index push_subscriptions_user_id_idx on public.push_subscriptions (user_id);

-- ---------------------------------------------------------------------------
-- staff_orders_v: security definer (runs as owner, so it sees profiles that
-- staff cannot read directly). The role check inside the body is what keeps
-- students out; do not remove it.
-- ---------------------------------------------------------------------------
create view public.staff_orders_v with (security_invoker = false) as
select
  o.id,
  o.code,
  o.status,
  o.total_paise,
  o.created_at,
  o.accepted_at,
  o.ready_at,
  o.collected_at,
  o.flagged_at,
  o.paid_at,
  o.slot_id,
  s.starts_at as slot_starts_at,
  o.student_id,
  p.full_name as student_name,
  p.reg_no,
  p.phone
from public.orders o
join public.slots s on s.id = o.slot_id
join public.profiles p on p.id = o.student_id
where public.current_role() in ('staff', 'admin');

-- ---------------------------------------------------------------------------
-- College-email guard on auth.users.
-- Allowed: <local>@<college_email_domain>, or app_metadata.provisioned = true.
-- app_metadata (raw_app_meta_data) can only be written with the service-role
-- admin API; sign-up data lands in raw_user_meta_data, which is never trusted.
--
-- GoTrue's admin createUser inserts the row first and writes app_metadata in a
-- later UPDATE of the same transaction, so at INSERT time a provisioned user
-- looks like any other. Inserts for the reserved staff login domain
-- (<id>@staff.oac.local, never deliverable) are therefore let through here and
-- verified at commit by verify_staff_login_provisioned() below.
-- ---------------------------------------------------------------------------
create function public.enforce_college_email()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  allowed text;
begin
  if coalesce(new.raw_app_meta_data ->> 'provisioned', '') = 'true' then
    return new;
  end if;

  if tg_op = 'INSERT' and new.email ~* '^[^@]+@staff\.oac\.local$' then
    return new;
  end if;

  select s.college_email_domain into allowed from public.app_settings s;

  if allowed is null
     or allowed = ''
     or new.email is null
     or new.email !~ '^[^@]+@[^@]+$'
     or lower(split_part(new.email, '@', 2)) <> allowed then
    raise exception 'Sign-up is restricted to college email addresses';
  end if;

  return new;
end;
$$;

create trigger enforce_college_email_insert
  before insert on auth.users
  for each row execute function public.enforce_college_email();

create trigger enforce_college_email_update
  before update of email on auth.users
  for each row
  when (old.email is distinct from new.email)
  execute function public.enforce_college_email();

-- Commit-time check: a staff-domain login must end the transaction provisioned.
-- Reads the row's final state (NEW is the version at INSERT time).
create function public.verify_staff_login_provisioned()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if exists (
    select 1
    from auth.users u
    where u.id = new.id
      and u.email ~* '^[^@]+@staff\.oac\.local$'
      and coalesce(u.raw_app_meta_data ->> 'provisioned', '') <> 'true'
  ) then
    raise exception 'Staff logins can only be created by an admin';
  end if;
  return null;
end;
$$;

create constraint trigger verify_staff_login_provisioned
  after insert on auth.users
  deferrable initially deferred
  for each row execute function public.verify_staff_login_provisioned();


-- ===================== 0002_rls.sql =====================

-- OAC pre-order: grants, row level security, realtime.
-- Writes to profiles, orders, order_items and slots.booked_count are not granted
-- to API roles at all; they happen only inside security-definer RPCs (later migrations)
-- or with the service-role key.

alter table public.app_settings enable row level security;
alter table public.profiles enable row level security;
alter table public.menu_items enable row level security;
alter table public.slots enable row level security;
alter table public.orders enable row level security;
alter table public.order_items enable row level security;
alter table public.push_subscriptions enable row level security;

-- ---------------------------------------------------------------------------
-- Privileges: start from nothing, then grant the minimum.
-- ---------------------------------------------------------------------------
revoke all on table
  public.app_settings, public.profiles, public.menu_items, public.slots,
  public.orders, public.order_items, public.push_subscriptions, public.staff_orders_v
from anon, authenticated;

revoke all on function public.current_role() from public, anon;
revoke all on function public.enforce_college_email() from public, anon, authenticated;
revoke all on function public.verify_staff_login_provisioned() from public, anon, authenticated;
grant execute on function public.current_role() to authenticated;

grant select on public.profiles, public.orders, public.order_items, public.staff_orders_v to authenticated;
grant select, insert, update, delete on public.menu_items to authenticated;
-- slots: admin may create, retime and resize; booked_count is RPC-only.
grant select, delete on public.slots to authenticated;
grant insert (starts_at, capacity), update (starts_at, capacity) on public.slots to authenticated;
grant select on public.app_settings to authenticated;
grant update (order_cutoff_minutes, no_show_hold_minutes, college_email_domain)
  on public.app_settings to authenticated;
grant select, insert, delete on public.push_subscriptions to authenticated;

-- ---------------------------------------------------------------------------
-- Policies. auth.uid() and current_role() are wrapped in selects so Postgres
-- evaluates them once per statement, not once per row.
-- ---------------------------------------------------------------------------
create policy profiles_select_self_or_admin on public.profiles
  for select to authenticated
  using (id = (select auth.uid()) or (select public.current_role()) = 'admin');

create policy orders_select_own on public.orders
  for select to authenticated
  using (student_id = (select auth.uid()));

create policy orders_select_staff on public.orders
  for select to authenticated
  using ((select public.current_role()) in ('staff', 'admin'));

create policy order_items_select_own on public.order_items
  for select to authenticated
  using (exists (
    select 1 from public.orders o
    where o.id = order_items.order_id and o.student_id = (select auth.uid())
  ));

create policy order_items_select_staff on public.order_items
  for select to authenticated
  using ((select public.current_role()) in ('staff', 'admin'));

create policy push_subscriptions_select_own on public.push_subscriptions
  for select to authenticated
  using (user_id = (select auth.uid()));

create policy push_subscriptions_insert_own on public.push_subscriptions
  for insert to authenticated
  with check (user_id = (select auth.uid()));

create policy push_subscriptions_delete_own on public.push_subscriptions
  for delete to authenticated
  using (user_id = (select auth.uid()));

create policy menu_items_select on public.menu_items
  for select to authenticated using (true);

create policy menu_items_admin_write on public.menu_items
  for all to authenticated
  using ((select public.current_role()) = 'admin')
  with check ((select public.current_role()) = 'admin');

create policy slots_select on public.slots
  for select to authenticated using (true);

create policy slots_admin_write on public.slots
  for all to authenticated
  using ((select public.current_role()) = 'admin')
  with check ((select public.current_role()) = 'admin');

create policy app_settings_select on public.app_settings
  for select to authenticated using (true);

create policy app_settings_admin_update on public.app_settings
  for update to authenticated
  using ((select public.current_role()) = 'admin')
  with check ((select public.current_role()) = 'admin');

-- ---------------------------------------------------------------------------
-- Realtime (postgres_changes respects the select policies above)
-- ---------------------------------------------------------------------------
alter publication supabase_realtime add table public.orders, public.slots;


-- ===================== 0003_order_rpcs.sql =====================

-- OAC pre-order: place_order and cancel_order.
-- Students never write orders directly (0002_rls.sql grants select only); these
-- security-definer functions are the only write path. Business rules raise a bare
-- error code as the message: SLOT_FULL, SLOT_CLOSED, DEFAULTER, ITEM_UNAVAILABLE,
-- EMPTY_ORDER, NOT_CANCELLABLE. Callers that are not active students get FORBIDDEN.

-- OAC- plus 5 characters from an alphabet without 0/1/I/O, readable on a phone.
create function public.generate_order_code()
returns text
language plpgsql
volatile
set search_path = ''
as $$
declare
  alphabet constant text := '23456789ABCDEFGHJKLMNPQRSTUVWXYZ';
  code text := 'OAC-';
begin
  for i in 1..5 loop
    code := code || substr(alphabet, 1 + floor(random() * length(alphabet))::int, 1);
  end loop;
  return code;
end;
$$;

create function public.place_order(p_slot_id uuid, p_items jsonb, p_request_id uuid)
returns public.orders
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
  v_profile public.profiles;
  v_existing public.orders;
  v_cutoff int;
  v_slot public.slots;
  v_total int;
  v_lines jsonb;
  v_found int;
  v_order public.orders;
  v_attempt int := 0;
begin
  if v_uid is null then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;

  -- Serialise retries and double-taps of the same request: the second caller waits
  -- here, then finds the first caller's order below instead of booking a second seat.
  perform pg_advisory_xact_lock(hashtextextended(v_uid::text || ':' || p_request_id::text, 0));

  select * into v_existing
  from public.orders o
  where o.student_id = v_uid and o.request_id = p_request_id;
  if found then
    return v_existing;
  end if;

  select * into v_profile from public.profiles p where p.id = v_uid;
  if not found or not v_profile.is_active or v_profile.role <> 'student' then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;
  if v_profile.is_defaulter then
    raise exception 'DEFAULTER';
  end if;

  -- A line without a positive integer quantity is not an order. Duplicate lines for the
  -- same item are merged (order_items is keyed by order and item). Malformed JSON is an
  -- empty order, not a server error.
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'EMPTY_ORDER';
  end if;

  begin
    if exists (
      select 1 from jsonb_to_recordset(p_items) as l(menu_item_id uuid, qty int)
      where l.menu_item_id is null or l.qty is null or l.qty <= 0
    ) then
      raise exception 'EMPTY_ORDER';
    end if;

    select jsonb_agg(jsonb_build_object('id', l.menu_item_id, 'qty', l.qty))
      into v_lines
    from (
      select r.menu_item_id, sum(r.qty)::int as qty
      from jsonb_to_recordset(p_items) as r(menu_item_id uuid, qty int)
      group by r.menu_item_id
    ) l;
  exception
    when others then
      raise exception 'EMPTY_ORDER';
  end;

  -- Current prices and availability, read before the seat is claimed so the hot slot
  -- row is locked for as short a time as possible. Client-sent prices are never read.
  select count(*), sum(m.price_paise::bigint * l.qty)
    into v_found, v_total
  from jsonb_to_recordset(v_lines) as l(id uuid, qty int)
  join public.menu_items m on m.id = l.id and m.is_available;
  if v_found <> jsonb_array_length(v_lines) then
    raise exception 'ITEM_UNAVAILABLE';
  end if;

  select s.order_cutoff_minutes into v_cutoff from public.app_settings s;

  -- Lock-free capacity claim: one atomic conditional UPDATE. Of N concurrent callers
  -- for the last seat, Postgres re-evaluates the WHERE for the waiters after the first
  -- commits, so exactly one wins.
  update public.slots s
  set booked_count = s.booked_count + 1
  where s.id = p_slot_id
    and s.booked_count < s.capacity
    and s.starts_at > now() + make_interval(mins => v_cutoff)
  returning * into v_slot;

  if not found then
    select * into v_slot from public.slots s where s.id = p_slot_id;
    if not found or v_slot.starts_at <= now() + make_interval(mins => v_cutoff) then
      raise exception 'SLOT_CLOSED';
    end if;
    raise exception 'SLOT_FULL';
  end if;

  loop
    v_attempt := v_attempt + 1;
    begin
      insert into public.orders (code, student_id, slot_id, total_paise, request_id)
      values (public.generate_order_code(), v_uid, p_slot_id, v_total, p_request_id)
      returning * into v_order;
      exit;
    exception when unique_violation then
      -- Only the code can collide here (the advisory lock rules out request_id).
      if v_attempt >= 10 then
        raise;
      end if;
    end;
  end loop;

  insert into public.order_items (order_id, menu_item_id, name, unit_price_paise, qty)
  select v_order.id, m.id, m.name, m.price_paise, l.qty
  from jsonb_to_recordset(v_lines) as l(id uuid, qty int)
  join public.menu_items m on m.id = l.id;

  return v_order;
end;
$$;

create function public.cancel_order(p_order_id uuid)
returns public.orders
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
  v_order public.orders;
begin
  if v_uid is null then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;

  -- Another student's order, a missing order and a non-cancellable one look the same.
  select * into v_order
  from public.orders o
  where o.id = p_order_id and o.student_id = v_uid and o.status = 'placed'
  for update;
  if not found then
    raise exception 'NOT_CANCELLABLE';
  end if;

  update public.orders o set status = 'cancelled' where o.id = v_order.id returning * into v_order;
  update public.slots s set booked_count = s.booked_count - 1 where s.id = v_order.slot_id;

  return v_order;
end;
$$;

revoke all on function public.generate_order_code() from public, anon, authenticated;
revoke all on function public.place_order(uuid, jsonb, uuid) from public, anon;
revoke all on function public.cancel_order(uuid) from public, anon;
grant execute on function public.place_order(uuid, jsonb, uuid) to authenticated;
grant execute on function public.cancel_order(uuid) to authenticated;


-- ===================== 0004_lifecycle_rpcs.sql =====================

-- OAC pre-order: staff lifecycle RPCs and defaulter rules.
-- accept_order, mark_ready, collect_order, flag_no_show are staff/admin only;
-- settle_no_show is admin only. Errors: FORBIDDEN (wrong or no role), ORDER_NOT_FOUND,
-- ILLEGAL_TRANSITION, HOLD_NOT_ELAPSED. Every function locks the order row first, then
-- (when it touches the defaulter flag) the student's profile row, so concurrent calls
-- never deadlock and the flag is recomputed against committed data.

-- Locks and returns the order, after checking the caller's role.
create function public.lock_order_for_staff(p_order_id uuid, p_admin_only boolean)
returns public.orders
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_role public.user_role := public.current_role();
  v_order public.orders;
begin
  if v_role is null or v_role = 'student' or (p_admin_only and v_role <> 'admin') then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;

  select * into v_order from public.orders o where o.id = p_order_id for update;
  if not found then
    raise exception 'ORDER_NOT_FOUND';
  end if;
  return v_order;
end;
$$;

-- Recomputes a student's defaulter flag: true while any no_show order is unpaid.
-- The explicit profile lock comes first so the exists() below runs in a fresh
-- statement, after any concurrent settle has committed.
create function public.refresh_defaulter(p_student_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform 1 from public.profiles p where p.id = p_student_id for update;
  update public.profiles p
  set is_defaulter = exists (
    select 1 from public.orders o
    where o.student_id = p_student_id and o.status = 'no_show' and o.paid_at is null
  )
  where p.id = p_student_id;
end;
$$;

create function public.accept_order(p_order_id uuid)
returns public.orders
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_order public.orders := public.lock_order_for_staff(p_order_id, false);
begin
  if v_order.status <> 'placed' then
    raise exception 'ILLEGAL_TRANSITION';
  end if;
  update public.orders o set status = 'accepted', accepted_at = now()
  where o.id = v_order.id returning * into v_order;
  return v_order;
end;
$$;

create function public.mark_ready(p_order_id uuid)
returns public.orders
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_order public.orders := public.lock_order_for_staff(p_order_id, false);
begin
  if v_order.status <> 'accepted' then
    raise exception 'ILLEGAL_TRANSITION';
  end if;
  update public.orders o set status = 'ready', ready_at = now()
  where o.id = v_order.id returning * into v_order;
  return v_order;
end;
$$;

-- ready → collected, or no_show → collected (a late arrival pays and takes the food).
create function public.collect_order(p_order_id uuid)
returns public.orders
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_order public.orders := public.lock_order_for_staff(p_order_id, false);
  v_was_no_show boolean;
begin
  if v_order.status not in ('ready', 'no_show') then
    raise exception 'ILLEGAL_TRANSITION';
  end if;
  v_was_no_show := v_order.status = 'no_show';

  update public.orders o set status = 'collected', collected_at = now(), paid_at = now()
  where o.id = v_order.id returning * into v_order;

  if v_was_no_show then
    perform public.refresh_defaulter(v_order.student_id);
  end if;
  return v_order;
end;
$$;

-- ready → no_show, only once the hold (no_show_hold_minutes after the slot starts) is over.
create function public.flag_no_show(p_order_id uuid)
returns public.orders
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_order public.orders := public.lock_order_for_staff(p_order_id, false);
  v_starts_at timestamptz;
  v_hold int;
begin
  if v_order.status <> 'ready' then
    raise exception 'ILLEGAL_TRANSITION';
  end if;

  select s.starts_at into v_starts_at from public.slots s where s.id = v_order.slot_id;
  select a.no_show_hold_minutes into v_hold from public.app_settings a;
  if now() < v_starts_at + make_interval(mins => v_hold) then
    raise exception 'HOLD_NOT_ELAPSED';
  end if;

  update public.orders o set status = 'no_show', flagged_at = now()
  where o.id = v_order.id returning * into v_order;

  perform 1 from public.profiles p where p.id = v_order.student_id for update;
  update public.profiles p set is_defaulter = true where p.id = v_order.student_id;
  return v_order;
end;
$$;

-- Admin records payment for a no_show order without handing it over.
create function public.settle_no_show(p_order_id uuid)
returns public.orders
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_order public.orders := public.lock_order_for_staff(p_order_id, true);
begin
  if v_order.status <> 'no_show' or v_order.paid_at is not null then
    raise exception 'ILLEGAL_TRANSITION';
  end if;
  update public.orders o set paid_at = now()
  where o.id = v_order.id returning * into v_order;

  perform public.refresh_defaulter(v_order.student_id);
  return v_order;
end;
$$;

revoke all on function public.lock_order_for_staff(uuid, boolean) from public, anon, authenticated;
revoke all on function public.refresh_defaulter(uuid) from public, anon, authenticated;
revoke all on function public.accept_order(uuid), public.mark_ready(uuid), public.collect_order(uuid),
  public.flag_no_show(uuid), public.settle_no_show(uuid) from public, anon;
grant execute on function public.accept_order(uuid), public.mark_ready(uuid), public.collect_order(uuid),
  public.flag_no_show(uuid), public.settle_no_show(uuid) to authenticated;


-- ===================== 0005_profile_rpc.sql =====================

-- OAC pre-order: student onboarding.
-- complete_profile is the only way a profile for a self-registered user comes to exist:
-- it always creates role 'student', so nobody can sign up into staff or admin. Staff and
-- admin profiles are created with the service-role key (create-admin.ts, createStaff).
-- Errors: INVALID_NAME, INVALID_PHONE, INVALID_REG_NO, REG_NO_TAKEN, PROFILE_EXISTS, FORBIDDEN.

create function public.complete_profile(p_full_name text, p_phone text, p_reg_no text)
returns public.profiles
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
  v_name text := regexp_replace(btrim(coalesce(p_full_name, '')), '\s+', ' ', 'g');
  v_phone text := regexp_replace(coalesce(p_phone, ''), '[\s-]', '', 'g');
  v_reg text := upper(btrim(coalesce(p_reg_no, '')));
  v_profile public.profiles;
  v_constraint text;
begin
  if v_uid is null then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;

  if exists (select 1 from public.profiles p where p.id = v_uid) then
    raise exception 'PROFILE_EXISTS';
  end if;

  if v_name = '' or length(v_name) > 100 then
    raise exception 'INVALID_NAME';
  end if;

  -- Ten-digit Indian mobile number, optionally written with +91 or 91.
  v_phone := regexp_replace(v_phone, '^(\+91|91)(?=[6-9][0-9]{9}$)', '');
  if v_phone !~ '^[6-9][0-9]{9}$' then
    raise exception 'INVALID_PHONE';
  end if;

  if v_reg = '' or length(v_reg) > 32 then
    raise exception 'INVALID_REG_NO';
  end if;

  begin
    insert into public.profiles (id, full_name, phone, reg_no, role)
    values (v_uid, v_name, v_phone, v_reg, 'student')
    returning * into v_profile;
  exception when unique_violation then
    get stacked diagnostics v_constraint = constraint_name;
    if v_constraint = 'profiles_pkey' then
      raise exception 'PROFILE_EXISTS';
    end if;
    raise exception 'REG_NO_TAKEN';
  end;

  return v_profile;
end;
$$;

revoke all on function public.complete_profile(text, text, text) from public, anon;
grant execute on function public.complete_profile(text, text, text) to authenticated;


-- ===================== 0006_admin_rpcs.sql =====================

-- OAC pre-order: admin RPCs for slots, and live menu updates.
-- Errors: FORBIDDEN (not an active admin), INVALID_RANGE, BELOW_BOOKED, SLOT_NOT_FOUND.

-- Slots for one campus day, every p_minutes from p_from up to (not including) p_to, in campus time.
-- Idempotent: a slot that already exists at that start time is left alone. Returns slots created.
create function public.generate_slots(p_day date, p_from time, p_to time, p_minutes int, p_capacity int)
returns int
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tz constant text := 'Asia/Kolkata';
  v_start timestamptz;
  v_end timestamptz;
  v_created int;
begin
  if public.current_role() is distinct from 'admin' then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;

  if p_day is null or p_from is null or p_to is null or p_minutes is null or p_capacity is null
     or p_minutes <= 0 or p_capacity <= 0 or p_to <= p_from then
    raise exception 'INVALID_RANGE';
  end if;

  v_start := (p_day + p_from) at time zone v_tz;
  v_end := (p_day + p_to) at time zone v_tz;

  -- A day has at most 1440 one-minute slots; refuse anything that would be a typo-sized insert.
  if (extract(epoch from (v_end - v_start)) / 60)::int / p_minutes > 288 then
    raise exception 'INVALID_RANGE';
  end if;

  insert into public.slots (starts_at, capacity)
  select s, p_capacity
  from generate_series(v_start, v_end - interval '1 microsecond', make_interval(mins => p_minutes)) as s
  on conflict (starts_at) do nothing;

  get diagnostics v_created = row_count;
  return v_created;
end;
$$;

create function public.set_slot_capacity(p_slot_id uuid, p_capacity int)
returns public.slots
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_slot public.slots;
begin
  if public.current_role() is distinct from 'admin' then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;
  if p_capacity is null or p_capacity <= 0 then
    raise exception 'INVALID_RANGE';
  end if;

  -- Lock the row so a seat claimed at the same instant is counted before the check.
  select * into v_slot from public.slots s where s.id = p_slot_id for update;
  if not found then
    raise exception 'SLOT_NOT_FOUND';
  end if;
  if p_capacity < v_slot.booked_count then
    raise exception 'BELOW_BOOKED';
  end if;

  update public.slots s set capacity = p_capacity where s.id = p_slot_id returning * into v_slot;
  return v_slot;
end;
$$;

revoke all on function public.generate_slots(date, time, time, int, int) from public, anon;
revoke all on function public.set_slot_capacity(uuid, int) from public, anon;
grant execute on function public.generate_slots(date, time, time, int, int) to authenticated;
grant execute on function public.set_slot_capacity(uuid, int) to authenticated;

-- The student menu follows admin edits (sold out, new items) without a refresh.
alter publication supabase_realtime add table public.menu_items;


-- ===================== 0007_push_rpc.sql =====================

-- OAC pre-order: push subscription registration.
-- A browser's push endpoint is globally unique. If someone else signed in on the same phone
-- earlier, a plain insert would fail on the unique endpoint, so registration is an upsert that
-- moves the endpoint to whoever is signed in now. Errors: INVALID_SUBSCRIPTION, FORBIDDEN.

create function public.upsert_push_subscription(p_endpoint text, p_p256dh text, p_auth text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
begin
  if v_uid is null or not exists (select 1 from public.profiles p where p.id = v_uid and p.is_active) then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;
  if coalesce(btrim(p_endpoint), '') = '' or coalesce(btrim(p_p256dh), '') = ''
     or coalesce(btrim(p_auth), '') = '' or length(p_endpoint) > 2048 then
    raise exception 'INVALID_SUBSCRIPTION';
  end if;

  insert into public.push_subscriptions (user_id, endpoint, p256dh, auth)
  values (v_uid, p_endpoint, p_p256dh, p_auth)
  on conflict (endpoint) do update
    set user_id = excluded.user_id, p256dh = excluded.p256dh, auth = excluded.auth;
end;
$$;

revoke all on function public.upsert_push_subscription(text, text, text) from public, anon;
grant execute on function public.upsert_push_subscription(text, text, text) to authenticated;


-- ===================== 0008_tenancy_schema.sql =====================

-- OAC platform: colleges, canteens and canteen-scoped access.
-- Every college has its own canteens; each canteen has its own menu, slots, staff and orders.
-- Today's single-canteen data is backfilled into one college (ait-pune) and one canteen (oac).
-- profiles.role keeps student | staff | admin: `admin` is the admin of profiles.college_id, and
-- the rank inside a canteen (staff | owner) lives in canteen_members.role.
-- app_settings stays until the sign-up guard moves to college_domains (later migration).

-- ---------------------------------------------------------------------------
-- Types. canteen_role is declared low to high so `role >= 'staff'` compares by rank.
-- ---------------------------------------------------------------------------
create type public.canteen_status as enum ('pending', 'approved', 'suspended');
create type public.canteen_role as enum ('staff', 'owner');

-- ---------------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------------
create table public.colleges (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  slug text not null unique check (slug ~ '^[a-z0-9-]{2,40}$'),
  timezone text not null default 'Asia/Kolkata',
  created_at timestamptz not null default now()
);

-- A sign-up email's domain picks the college. Domains are public (the login form reads them).
create table public.college_domains (
  domain text primary key check (domain = lower(domain) and domain !~ '[@[:space:]]'),
  college_id uuid not null references public.colleges (id) on delete cascade
);

create table public.canteens (
  id uuid primary key default gen_random_uuid(),
  college_id uuid not null references public.colleges (id),
  name text not null,
  slug text not null check (slug ~ '^[a-z0-9-]{2,40}$'),
  code_prefix text not null check (code_prefix ~ '^[A-Z0-9]{2,5}$'),
  status public.canteen_status not null default 'pending',
  description text,
  order_cutoff_minutes int not null default 5 check (order_cutoff_minutes >= 0),
  no_show_hold_minutes int not null default 15 check (no_show_hold_minutes >= 0),
  created_at timestamptz not null default now(),
  unique (college_id, slug),
  unique (college_id, code_prefix)
);

create table public.canteen_members (
  user_id uuid references public.profiles (id) on delete cascade,
  canteen_id uuid references public.canteens (id) on delete cascade,
  role public.canteen_role not null default 'staff',
  primary key (user_id, canteen_id)
);

-- ---------------------------------------------------------------------------
-- Backfill rows: today's deployment becomes college ait-pune with canteen oac.
-- ---------------------------------------------------------------------------
insert into public.colleges (name, slug)
values ('Army Institute of Technology, Pune', 'ait-pune');

insert into public.canteens (college_id, name, slug, code_prefix, status, order_cutoff_minutes, no_show_hold_minutes)
select c.id, 'Open Area Canteen', 'oac', 'OAC', 'approved', s.order_cutoff_minutes, s.no_show_hold_minutes
from public.colleges c
cross join public.app_settings s
where c.slug = 'ait-pune';

insert into public.college_domains (domain, college_id)
select s.college_email_domain, c.id
from public.app_settings s
cross join public.colleges c
where c.slug = 'ait-pune' and s.college_email_domain is not null;

-- ---------------------------------------------------------------------------
-- Tenancy columns: add nullable, backfill, then require.
-- ---------------------------------------------------------------------------
alter table public.profiles add column college_id uuid references public.colleges (id);
alter table public.menu_items add column canteen_id uuid references public.canteens (id);
alter table public.slots add column canteen_id uuid references public.canteens (id);
alter table public.orders add column canteen_id uuid references public.canteens (id);

update public.profiles set college_id = (select c.id from public.colleges c where c.slug = 'ait-pune');
update public.menu_items set canteen_id = (select k.id from public.canteens k where k.slug = 'oac');
update public.slots set canteen_id = (select k.id from public.canteens k where k.slug = 'oac');
update public.orders set canteen_id = (select k.id from public.canteens k where k.slug = 'oac');

alter table public.profiles alter column college_id set not null;
alter table public.menu_items alter column canteen_id set not null;
alter table public.slots alter column canteen_id set not null;
alter table public.orders alter column canteen_id set not null;

-- ---------------------------------------------------------------------------
-- Constraints and indexes. Two canteens may open a slot at the same minute.
-- ---------------------------------------------------------------------------
alter table public.slots drop constraint slots_starts_at_key;
alter table public.slots add constraint slots_canteen_id_starts_at_key unique (canteen_id, starts_at);

create index canteen_members_canteen_id_idx on public.canteen_members (canteen_id);
create index menu_items_canteen_id_sort_idx on public.menu_items (canteen_id, sort);
create index orders_canteen_id_status_idx on public.orders (canteen_id, status);
create index order_items_menu_item_id_idx on public.order_items (menu_item_id);

-- ---------------------------------------------------------------------------
-- Access helpers. Both return nothing useful when signed out, without a profile,
-- or deactivated.
-- ---------------------------------------------------------------------------

-- The caller's college, or NULL.
create function public.current_college_id()
returns uuid
language sql
stable
security definer
set search_path = ''
as $$
  select p.college_id from public.profiles p where p.id = (select auth.uid()) and p.is_active
$$;

-- True when the caller works at the canteen with at least p_min_role, or is the admin of the
-- canteen's college. Never true for students, even with a stray membership row.
create function public.has_canteen_role(p_canteen_id uuid, p_min_role public.canteen_role)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.profiles p
    where p.id = (select auth.uid())
      and p.is_active
      and p.role in ('staff', 'admin')
      and (
        exists (
          select 1 from public.canteen_members m
          where m.user_id = p.id and m.canteen_id = p_canteen_id and m.role >= p_min_role
        )
        or (
          p.role = 'admin'
          and exists (
            select 1 from public.canteens k
            where k.id = p_canteen_id and k.college_id = p.college_id
          )
        )
      )
  )
$$;

-- ---------------------------------------------------------------------------
-- staff_orders_v: security definer (runs as owner, so it sees profiles that
-- staff cannot read directly). The canteen check inside the body is what keeps
-- students and other canteens' staff out; do not remove it.
-- ---------------------------------------------------------------------------
drop view public.staff_orders_v;

create view public.staff_orders_v with (security_invoker = false) as
select
  o.id,
  o.code,
  o.status,
  o.total_paise,
  o.created_at,
  o.accepted_at,
  o.ready_at,
  o.collected_at,
  o.flagged_at,
  o.paid_at,
  o.slot_id,
  s.starts_at as slot_starts_at,
  o.student_id,
  p.full_name as student_name,
  p.reg_no,
  p.phone,
  o.canteen_id,
  k.name as canteen_name
from public.orders o
join public.slots s on s.id = o.slot_id
join public.profiles p on p.id = o.student_id
join public.canteens k on k.id = o.canteen_id
where public.has_canteen_role(o.canteen_id, 'staff');

-- ---------------------------------------------------------------------------
-- Privileges: start from nothing, then grant the minimum. Memberships, colleges
-- and canteens are written only with the service-role key.
-- ---------------------------------------------------------------------------
alter table public.colleges enable row level security;
alter table public.college_domains enable row level security;
alter table public.canteens enable row level security;
alter table public.canteen_members enable row level security;

revoke all on table
  public.colleges, public.college_domains, public.canteens, public.canteen_members, public.staff_orders_v
from anon, authenticated;

revoke all on function public.current_college_id() from public, anon;
revoke all on function public.has_canteen_role(uuid, public.canteen_role) from public, anon;
grant execute on function public.current_college_id() to authenticated;
grant execute on function public.has_canteen_role(uuid, public.canteen_role) to authenticated;

grant select on public.colleges, public.canteens, public.canteen_members, public.staff_orders_v to authenticated;
grant select on public.college_domains to anon, authenticated;
grant insert (canteen_id), update (canteen_id) on public.slots to authenticated;

-- ---------------------------------------------------------------------------
-- Policies. auth.uid(), current_role(), current_college_id() and has_canteen_role()
-- are wrapped in selects, as in 0002_rls.sql.
-- ---------------------------------------------------------------------------
create policy colleges_select_own on public.colleges
  for select to authenticated
  using (id = (select public.current_college_id()));

create policy college_domains_select on public.college_domains
  for select to anon, authenticated
  using (true);

create policy canteens_select on public.canteens
  for select to authenticated
  using (
    (status = 'approved' and college_id = (select public.current_college_id()))
    or (select public.has_canteen_role(id, 'staff'))
  );

create policy canteen_members_select on public.canteen_members
  for select to authenticated
  using (user_id = (select auth.uid()) or (select public.has_canteen_role(canteen_id, 'owner')));

-- profiles: self, or the admin of the same college.
drop policy profiles_select_self_or_admin on public.profiles;
create policy profiles_select_self_or_college_admin on public.profiles
  for select to authenticated
  using (
    id = (select auth.uid())
    or ((select public.current_role()) = 'admin' and college_id = (select public.current_college_id()))
  );

-- orders and order_items: the canteen's staff (and the college admin).
drop policy orders_select_staff on public.orders;
create policy orders_select_staff on public.orders
  for select to authenticated
  using ((select public.has_canteen_role(canteen_id, 'staff')));

drop policy order_items_select_staff on public.order_items;
create policy order_items_select_staff on public.order_items
  for select to authenticated
  using (exists (
    select 1 from public.orders o
    where o.id = order_items.order_id and (select public.has_canteen_role(o.canteen_id, 'staff'))
  ));

-- menu_items and slots: readable when the canteen is approved and in the caller's college
-- (students), or by the canteen's staff; written by its owner (or the college admin).
drop policy menu_items_select on public.menu_items;
drop policy menu_items_admin_write on public.menu_items;

create policy menu_items_select on public.menu_items
  for select to authenticated
  using (
    exists (
      select 1 from public.canteens k
      where k.id = menu_items.canteen_id
        and k.status = 'approved'
        and k.college_id = (select public.current_college_id())
    )
    or (select public.has_canteen_role(canteen_id, 'staff'))
  );

create policy menu_items_owner_insert on public.menu_items
  for insert to authenticated
  with check ((select public.has_canteen_role(canteen_id, 'owner')));

create policy menu_items_owner_update on public.menu_items
  for update to authenticated
  using ((select public.has_canteen_role(canteen_id, 'owner')))
  with check ((select public.has_canteen_role(canteen_id, 'owner')));

create policy menu_items_owner_delete on public.menu_items
  for delete to authenticated
  using ((select public.has_canteen_role(canteen_id, 'owner')));

drop policy slots_select on public.slots;
drop policy slots_admin_write on public.slots;

create policy slots_select on public.slots
  for select to authenticated
  using (
    exists (
      select 1 from public.canteens k
      where k.id = slots.canteen_id
        and k.status = 'approved'
        and k.college_id = (select public.current_college_id())
    )
    or (select public.has_canteen_role(canteen_id, 'staff'))
  );

create policy slots_owner_insert on public.slots
  for insert to authenticated
  with check ((select public.has_canteen_role(canteen_id, 'owner')));

create policy slots_owner_update on public.slots
  for update to authenticated
  using ((select public.has_canteen_role(canteen_id, 'owner')))
  with check ((select public.has_canteen_role(canteen_id, 'owner')));

create policy slots_owner_delete on public.slots
  for delete to authenticated
  using ((select public.has_canteen_role(canteen_id, 'owner')));


-- ===================== 0009_tenancy_rpcs.sql =====================

-- OAC platform: canteen-aware RPCs.
-- Every order, lifecycle and slot RPC now acts inside one canteen: place_order takes the
-- canteen the cart belongs to, staff and owners act only on their own canteen's rows (the
-- college admin on every canteen of the college), and cutoff, no-show hold, timezone and
-- order-code prefix come from the canteen and its college instead of app_settings.
-- complete_profile picks the student's college from the email domain.
-- New error codes: CANTEEN_UNAVAILABLE (place_order), NO_COLLEGE (complete_profile).
-- cancel_order, refresh_defaulter and upsert_push_subscription are unchanged.

-- ---------------------------------------------------------------------------
-- Order code: <canteen prefix>- plus 5 characters from an alphabet without 0/1/I/O.
-- ---------------------------------------------------------------------------
drop function public.generate_order_code();

create function public.generate_order_code(p_prefix text)
returns text
language plpgsql
volatile
set search_path = ''
as $$
declare
  alphabet constant text := '23456789ABCDEFGHJKLMNPQRSTUVWXYZ';
  code text := p_prefix || '-';
begin
  for i in 1..5 loop
    code := code || substr(alphabet, 1 + floor(random() * length(alphabet))::int, 1);
  end loop;
  return code;
end;
$$;

-- ---------------------------------------------------------------------------
-- place_order. Errors: FORBIDDEN, DEFAULTER, CANTEEN_UNAVAILABLE, EMPTY_ORDER,
-- ITEM_UNAVAILABLE, SLOT_CLOSED, SLOT_FULL.
-- ---------------------------------------------------------------------------
drop function public.place_order(uuid, jsonb, uuid);

create function public.place_order(p_canteen_id uuid, p_slot_id uuid, p_items jsonb, p_request_id uuid)
returns public.orders
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
  v_profile public.profiles;
  v_canteen public.canteens;
  v_existing public.orders;
  v_slot public.slots;
  v_total int;
  v_lines jsonb;
  v_found int;
  v_order public.orders;
  v_attempt int := 0;
begin
  if v_uid is null then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;

  -- Serialise retries and double-taps of the same request: the second caller waits
  -- here, then finds the first caller's order below instead of booking a second seat.
  perform pg_advisory_xact_lock(hashtextextended(v_uid::text || ':' || p_request_id::text, 0));

  select * into v_existing
  from public.orders o
  where o.student_id = v_uid and o.request_id = p_request_id;
  if found then
    return v_existing;
  end if;

  select * into v_profile from public.profiles p where p.id = v_uid;
  if not found or not v_profile.is_active or v_profile.role <> 'student' then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;
  if v_profile.is_defaulter then
    raise exception 'DEFAULTER';
  end if;

  -- Only approved canteens of the student's own college take orders. A missing, pending,
  -- suspended or other-college canteen look the same.
  select * into v_canteen from public.canteens k where k.id = p_canteen_id;
  if not found or v_canteen.status <> 'approved' or v_canteen.college_id <> v_profile.college_id then
    raise exception 'CANTEEN_UNAVAILABLE';
  end if;

  -- A line without a positive integer quantity is not an order. Duplicate lines for the
  -- same item are merged (order_items is keyed by order and item). Malformed JSON is an
  -- empty order, not a server error.
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'EMPTY_ORDER';
  end if;

  begin
    if exists (
      select 1 from jsonb_to_recordset(p_items) as l(menu_item_id uuid, qty int)
      where l.menu_item_id is null or l.qty is null or l.qty <= 0
    ) then
      raise exception 'EMPTY_ORDER';
    end if;

    select jsonb_agg(jsonb_build_object('id', l.menu_item_id, 'qty', l.qty))
      into v_lines
    from (
      select r.menu_item_id, sum(r.qty)::int as qty
      from jsonb_to_recordset(p_items) as r(menu_item_id uuid, qty int)
      group by r.menu_item_id
    ) l;
  exception
    when others then
      raise exception 'EMPTY_ORDER';
  end;

  -- Current prices and availability, read before the seat is claimed so the hot slot
  -- row is locked for as short a time as possible. Client-sent prices are never read.
  -- An item of another canteen counts as unavailable.
  select count(*), sum(m.price_paise::bigint * l.qty)
    into v_found, v_total
  from jsonb_to_recordset(v_lines) as l(id uuid, qty int)
  join public.menu_items m on m.id = l.id and m.is_available and m.canteen_id = p_canteen_id;
  if v_found <> jsonb_array_length(v_lines) then
    raise exception 'ITEM_UNAVAILABLE';
  end if;

  -- Lock-free capacity claim: one atomic conditional UPDATE. Of N concurrent callers
  -- for the last seat, Postgres re-evaluates the WHERE for the waiters after the first
  -- commits, so exactly one wins. A slot of another canteen never matches, so no seat
  -- is booked anywhere for a mismatched slot.
  update public.slots s
  set booked_count = s.booked_count + 1
  where s.id = p_slot_id
    and s.canteen_id = p_canteen_id
    and s.booked_count < s.capacity
    and s.starts_at > now() + make_interval(mins => v_canteen.order_cutoff_minutes)
  returning * into v_slot;

  if not found then
    -- Missing, in another canteen or past the cutoff: SLOT_CLOSED. Otherwise it is full.
    select * into v_slot from public.slots s where s.id = p_slot_id;
    if not found
       or v_slot.canteen_id <> p_canteen_id
       or v_slot.starts_at <= now() + make_interval(mins => v_canteen.order_cutoff_minutes) then
      raise exception 'SLOT_CLOSED';
    end if;
    raise exception 'SLOT_FULL';
  end if;

  loop
    v_attempt := v_attempt + 1;
    begin
      insert into public.orders (canteen_id, code, student_id, slot_id, total_paise, request_id)
      values (p_canteen_id, public.generate_order_code(v_canteen.code_prefix), v_uid, p_slot_id, v_total, p_request_id)
      returning * into v_order;
      exit;
    exception when unique_violation then
      -- Only the code can collide here (the advisory lock rules out request_id).
      if v_attempt >= 10 then
        raise;
      end if;
    end;
  end loop;

  insert into public.order_items (order_id, menu_item_id, name, unit_price_paise, qty)
  select v_order.id, m.id, m.name, m.price_paise, l.qty
  from jsonb_to_recordset(v_lines) as l(id uuid, qty int)
  join public.menu_items m on m.id = l.id;

  return v_order;
end;
$$;

-- ---------------------------------------------------------------------------
-- Staff lifecycle. Errors: FORBIDDEN (wrong role, or not this canteen's staff),
-- ORDER_NOT_FOUND, ILLEGAL_TRANSITION, HOLD_NOT_ELAPSED. Locking order is unchanged:
-- the order row first, then (when the defaulter flag moves) the student's profile row.
-- A suspended canteen's existing orders still run through the lifecycle.
-- ---------------------------------------------------------------------------
drop function public.accept_order(uuid);
drop function public.mark_ready(uuid);
drop function public.collect_order(uuid);
drop function public.flag_no_show(uuid);
drop function public.settle_no_show(uuid);
drop function public.lock_order_for_staff(uuid, boolean);

-- Locks and returns the order. The role pre-check runs before the lock so students never
-- take a row lock; the canteen check needs the row, so it runs after. A missing order is
-- ORDER_NOT_FOUND for any staff caller, as before.
create function public.lock_order_for_staff(p_order_id uuid, p_min_role public.canteen_role)
returns public.orders
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_role public.user_role := public.current_role();
  v_order public.orders;
begin
  if v_role is null or v_role not in ('staff', 'admin') then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;

  select * into v_order from public.orders o where o.id = p_order_id for update;
  if not found then
    raise exception 'ORDER_NOT_FOUND';
  end if;

  if not public.has_canteen_role(v_order.canteen_id, p_min_role) then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;
  return v_order;
end;
$$;

create function public.accept_order(p_order_id uuid)
returns public.orders
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_order public.orders := public.lock_order_for_staff(p_order_id, 'staff');
begin
  if v_order.status <> 'placed' then
    raise exception 'ILLEGAL_TRANSITION';
  end if;
  update public.orders o set status = 'accepted', accepted_at = now()
  where o.id = v_order.id returning * into v_order;
  return v_order;
end;
$$;

create function public.mark_ready(p_order_id uuid)
returns public.orders
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_order public.orders := public.lock_order_for_staff(p_order_id, 'staff');
begin
  if v_order.status <> 'accepted' then
    raise exception 'ILLEGAL_TRANSITION';
  end if;
  update public.orders o set status = 'ready', ready_at = now()
  where o.id = v_order.id returning * into v_order;
  return v_order;
end;
$$;

-- ready → collected, or no_show → collected (a late arrival pays and takes the food).
create function public.collect_order(p_order_id uuid)
returns public.orders
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_order public.orders := public.lock_order_for_staff(p_order_id, 'staff');
  v_was_no_show boolean;
begin
  if v_order.status not in ('ready', 'no_show') then
    raise exception 'ILLEGAL_TRANSITION';
  end if;
  v_was_no_show := v_order.status = 'no_show';

  update public.orders o set status = 'collected', collected_at = now(), paid_at = now()
  where o.id = v_order.id returning * into v_order;

  if v_was_no_show then
    perform public.refresh_defaulter(v_order.student_id);
  end if;
  return v_order;
end;
$$;

-- ready → no_show, only once the hold (the canteen's no_show_hold_minutes after the slot
-- starts) is over.
create function public.flag_no_show(p_order_id uuid)
returns public.orders
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_order public.orders := public.lock_order_for_staff(p_order_id, 'staff');
  v_starts_at timestamptz;
  v_hold int;
begin
  if v_order.status <> 'ready' then
    raise exception 'ILLEGAL_TRANSITION';
  end if;

  select s.starts_at into v_starts_at from public.slots s where s.id = v_order.slot_id;
  select k.no_show_hold_minutes into v_hold from public.canteens k where k.id = v_order.canteen_id;
  if now() < v_starts_at + make_interval(mins => v_hold) then
    raise exception 'HOLD_NOT_ELAPSED';
  end if;

  update public.orders o set status = 'no_show', flagged_at = now()
  where o.id = v_order.id returning * into v_order;

  perform 1 from public.profiles p where p.id = v_order.student_id for update;
  update public.profiles p set is_defaulter = true where p.id = v_order.student_id;
  return v_order;
end;
$$;

-- The canteen's owner (or the college admin) records payment for a no_show order
-- without handing it over.
create function public.settle_no_show(p_order_id uuid)
returns public.orders
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_order public.orders := public.lock_order_for_staff(p_order_id, 'owner');
begin
  if v_order.status <> 'no_show' or v_order.paid_at is not null then
    raise exception 'ILLEGAL_TRANSITION';
  end if;
  update public.orders o set paid_at = now()
  where o.id = v_order.id returning * into v_order;

  perform public.refresh_defaulter(v_order.student_id);
  return v_order;
end;
$$;

-- ---------------------------------------------------------------------------
-- Slots. Errors: FORBIDDEN (not the canteen's owner or college admin), INVALID_RANGE,
-- BELOW_BOOKED, SLOT_NOT_FOUND.
-- ---------------------------------------------------------------------------
drop function public.generate_slots(date, time, time, int, int);
drop function public.set_slot_capacity(uuid, int);

-- Slots for one campus day of one canteen, every p_minutes from p_from up to (not including)
-- p_to, in the college's timezone. Idempotent: a slot that already exists at that start time
-- in this canteen is left alone. Returns slots created.
create function public.generate_slots(
  p_canteen_id uuid, p_day date, p_from time, p_to time, p_minutes int, p_capacity int
)
returns int
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tz text;
  v_start timestamptz;
  v_end timestamptz;
  v_created int;
begin
  if not public.has_canteen_role(p_canteen_id, 'owner') then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;

  if p_day is null or p_from is null or p_to is null or p_minutes is null or p_capacity is null
     or p_minutes <= 0 or p_capacity <= 0 or p_to <= p_from then
    raise exception 'INVALID_RANGE';
  end if;

  select c.timezone into v_tz
  from public.canteens k
  join public.colleges c on c.id = k.college_id
  where k.id = p_canteen_id;

  v_start := (p_day + p_from) at time zone v_tz;
  v_end := (p_day + p_to) at time zone v_tz;

  -- A day has at most 1440 one-minute slots; refuse anything that would be a typo-sized insert.
  if (extract(epoch from (v_end - v_start)) / 60)::int / p_minutes > 288 then
    raise exception 'INVALID_RANGE';
  end if;

  insert into public.slots (canteen_id, starts_at, capacity)
  select p_canteen_id, s, p_capacity
  from generate_series(v_start, v_end - interval '1 microsecond', make_interval(mins => p_minutes)) as s
  on conflict (canteen_id, starts_at) do nothing;

  get diagnostics v_created = row_count;
  return v_created;
end;
$$;

create function public.set_slot_capacity(p_slot_id uuid, p_capacity int)
returns public.slots
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_role public.user_role := public.current_role();
  v_slot public.slots;
begin
  -- Role pre-check before the lock so students never take a row lock.
  if v_role is null or v_role not in ('staff', 'admin') then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;
  if p_capacity is null or p_capacity <= 0 then
    raise exception 'INVALID_RANGE';
  end if;

  -- Lock the row so a seat claimed at the same instant is counted before the check.
  select * into v_slot from public.slots s where s.id = p_slot_id for update;
  if not found then
    raise exception 'SLOT_NOT_FOUND';
  end if;
  if not public.has_canteen_role(v_slot.canteen_id, 'owner') then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;
  if p_capacity < v_slot.booked_count then
    raise exception 'BELOW_BOOKED';
  end if;

  update public.slots s set capacity = p_capacity where s.id = p_slot_id returning * into v_slot;
  return v_slot;
end;
$$;

-- ---------------------------------------------------------------------------
-- complete_profile. Errors: INVALID_NAME, INVALID_PHONE, INVALID_REG_NO, REG_NO_TAKEN,
-- PROFILE_EXISTS, NO_COLLEGE, FORBIDDEN. The college comes from the caller's email domain.
-- ---------------------------------------------------------------------------
drop function public.complete_profile(text, text, text);

create function public.complete_profile(p_full_name text, p_phone text, p_reg_no text)
returns public.profiles
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
  v_name text := regexp_replace(btrim(coalesce(p_full_name, '')), '\s+', ' ', 'g');
  v_phone text := regexp_replace(coalesce(p_phone, ''), '[\s-]', '', 'g');
  v_reg text := upper(btrim(coalesce(p_reg_no, '')));
  v_college_id uuid;
  v_profile public.profiles;
  v_constraint text;
begin
  if v_uid is null then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;

  if exists (select 1 from public.profiles p where p.id = v_uid) then
    raise exception 'PROFILE_EXISTS';
  end if;

  if v_name = '' or length(v_name) > 100 then
    raise exception 'INVALID_NAME';
  end if;

  -- Ten-digit Indian mobile number, optionally written with +91 or 91.
  v_phone := regexp_replace(v_phone, '^(\+91|91)(?=[6-9][0-9]{9}$)', '');
  if v_phone !~ '^[6-9][0-9]{9}$' then
    raise exception 'INVALID_PHONE';
  end if;

  if v_reg = '' or length(v_reg) > 32 then
    raise exception 'INVALID_REG_NO';
  end if;

  -- A session whose auth user is gone (e.g. the database was reset) gets the error the
  -- profile's foreign key used to raise, so the app still ends that stale session.
  if not exists (select 1 from auth.users u where u.id = v_uid) then
    raise exception 'SESSION_EXPIRED' using errcode = '23503';
  end if;

  select d.college_id into v_college_id
  from auth.users u
  join public.college_domains d on d.domain = lower(split_part(u.email, '@', 2))
  where u.id = v_uid;
  if v_college_id is null then
    raise exception 'NO_COLLEGE';
  end if;

  begin
    insert into public.profiles (id, full_name, phone, reg_no, role, college_id)
    values (v_uid, v_name, v_phone, v_reg, 'student', v_college_id)
    returning * into v_profile;
  exception when unique_violation then
    get stacked diagnostics v_constraint = constraint_name;
    if v_constraint = 'profiles_pkey' then
      raise exception 'PROFILE_EXISTS';
    end if;
    raise exception 'REG_NO_TAKEN';
  end;

  return v_profile;
end;
$$;

-- ---------------------------------------------------------------------------
-- Privileges: the helpers stay internal; every RPC is for signed-in callers only.
-- ---------------------------------------------------------------------------
revoke all on function public.generate_order_code(text) from public, anon, authenticated;
revoke all on function public.lock_order_for_staff(uuid, public.canteen_role) from public, anon, authenticated;

revoke all on function
  public.place_order(uuid, uuid, jsonb, uuid),
  public.accept_order(uuid), public.mark_ready(uuid), public.collect_order(uuid),
  public.flag_no_show(uuid), public.settle_no_show(uuid),
  public.generate_slots(uuid, date, time, time, int, int), public.set_slot_capacity(uuid, int),
  public.complete_profile(text, text, text)
from public, anon;

grant execute on function
  public.place_order(uuid, uuid, jsonb, uuid),
  public.accept_order(uuid), public.mark_ready(uuid), public.collect_order(uuid),
  public.flag_no_show(uuid), public.settle_no_show(uuid),
  public.generate_slots(uuid, date, time, time, int, int), public.set_slot_capacity(uuid, int),
  public.complete_profile(text, text, text)
to authenticated;


-- ===================== 0010_menu_tags.sql =====================

-- AI assistant: menu items carry descriptor tags and the meal moments they suit.
--   tags          one diet tag (veg | non-veg | egg) plus descriptors
--                 (hot cold light heavy spicy sweet quick filling drink snack meal)
--   meal_moments  any of breakfast | lunch | snack | dinner | late
-- Both default to empty, so items without tags simply score on nothing in the rules engine.
alter table public.menu_items
  add column tags text[] not null default '{}',
  add column meal_moments text[] not null default '{}';


-- ===================== 0011_popular_items.sql =====================

-- Popular here: how many orders each dish of a canteen got lately.
-- Counts only, never a student id. A caller sees rows when they are signed in and belong to the
-- canteen's college, or work at the canteen; everyone else gets zero rows.
--   p_days   look-back window, clamped to 1..90
--   p_limit  rows returned, clamped to 1..20
-- An order counts once however many of the dish it holds; cancelled and no_show orders and
-- sold-out dishes do not count.
create function public.popular_items(p_canteen_id uuid, p_days int default 30, p_limit int default 8)
returns table (menu_item_id uuid, orders bigint)
language sql
stable
security definer
set search_path = ''
as $$
  select oi.menu_item_id, count(distinct o.id) as orders
  from public.order_items oi
  join public.orders o on o.id = oi.order_id
  join public.menu_items m on m.id = oi.menu_item_id
  join public.canteens c on c.id = m.canteen_id
  where m.canteen_id = p_canteen_id
    and m.is_available
    and o.status not in ('cancelled', 'no_show')
    and o.created_at >= now() - make_interval(days => greatest(1, least(coalesce(p_days, 30), 90)))
    and (select auth.uid()) is not null
    and (
      c.college_id = (select public.current_college_id())
      or (select public.has_canteen_role(p_canteen_id, 'staff'))
    )
  group by oi.menu_item_id, m.name
  order by count(distinct o.id) desc, m.name
  limit greatest(1, least(coalesce(p_limit, 8), 20))
$$;

revoke all on function public.popular_items(uuid, int, int) from public, anon;
grant execute on function public.popular_items(uuid, int, int) to authenticated;


-- ===================== 0012_order_feedback.sql =====================

-- OAC: star feedback after delivery.
-- A student rates an order once it is collected (the counter handed the food over): 1 to 5 stars
-- and an optional comment of up to 500 characters, one per order. Staff of the order's canteen
-- (and the college admin) read it through staff_feedback_v. Students write only through
-- submit_feedback; the table itself takes no client writes.
-- Errors raised by submit_feedback: ORDER_NOT_FOUND, NOT_COLLECTED, INVALID_RATING,
-- INVALID_COMMENT, ALREADY_SUBMITTED.

-- ---------------------------------------------------------------------------
-- Table
-- ---------------------------------------------------------------------------
create table public.order_feedback (
  order_id uuid primary key references public.orders (id) on delete cascade,
  canteen_id uuid not null references public.canteens (id),
  student_id uuid not null references public.profiles (id),
  rating int not null check (rating between 1 and 5),
  comment text check (comment is null or char_length(comment) <= 500),
  created_at timestamptz not null default now()
);

create index order_feedback_canteen_id_created_at_idx on public.order_feedback (canteen_id, created_at desc);

-- ---------------------------------------------------------------------------
-- submit_feedback. The order row is locked first, so a double tap queues behind the first
-- call and finds its feedback; the unique violation handler covers any other race.
-- ---------------------------------------------------------------------------
create function public.submit_feedback(p_order_id uuid, p_rating int, p_comment text)
returns public.order_feedback
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
  v_comment text := nullif(btrim(coalesce(p_comment, '')), '');
  v_order public.orders;
  v_feedback public.order_feedback;
begin
  if v_uid is null then
    raise exception 'FORBIDDEN' using errcode = '42501';
  end if;

  if p_rating is null or p_rating < 1 or p_rating > 5 then
    raise exception 'INVALID_RATING';
  end if;
  if v_comment is not null and char_length(v_comment) > 500 then
    raise exception 'INVALID_COMMENT';
  end if;

  -- Only an active student can rate, and only their own order. Anything else looks the same.
  if not exists (
    select 1 from public.profiles p
    where p.id = v_uid and p.is_active and p.role = 'student'
  ) then
    raise exception 'ORDER_NOT_FOUND';
  end if;

  select * into v_order
  from public.orders o
  where o.id = p_order_id and o.student_id = v_uid
  for update;
  if not found then
    raise exception 'ORDER_NOT_FOUND';
  end if;

  if v_order.status <> 'collected' then
    raise exception 'NOT_COLLECTED';
  end if;

  if exists (select 1 from public.order_feedback f where f.order_id = v_order.id) then
    raise exception 'ALREADY_SUBMITTED';
  end if;

  begin
    insert into public.order_feedback (order_id, canteen_id, student_id, rating, comment)
    values (v_order.id, v_order.canteen_id, v_uid, p_rating, v_comment)
    returning * into v_feedback;
  exception when unique_violation then
    raise exception 'ALREADY_SUBMITTED';
  end;

  return v_feedback;
end;
$$;

-- ---------------------------------------------------------------------------
-- staff_feedback_v: security definer (runs as owner, so it sees student names and order
-- lines that staff cannot read directly). The canteen check inside the body is what keeps
-- students and other canteens' staff out; do not remove it.
-- ---------------------------------------------------------------------------
create view public.staff_feedback_v with (security_invoker = false) as
select
  f.order_id,
  f.canteen_id,
  f.rating,
  f.comment,
  f.created_at,
  o.code as order_code,
  p.full_name as student_name,
  coalesce(
    (
      select string_agg(oi.qty || '× ' || oi.name, ', ' order by oi.name)
      from public.order_items oi
      where oi.order_id = f.order_id
    ),
    ''
  ) as items
from public.order_feedback f
join public.orders o on o.id = f.order_id
join public.profiles p on p.id = f.student_id
where public.has_canteen_role(f.canteen_id, 'staff');

-- ---------------------------------------------------------------------------
-- Privileges and policies. No client writes: students go through submit_feedback.
-- ---------------------------------------------------------------------------
alter table public.order_feedback enable row level security;

revoke all on table public.order_feedback, public.staff_feedback_v from anon, authenticated;
grant select on public.order_feedback, public.staff_feedback_v to authenticated;

create policy order_feedback_select_own on public.order_feedback
  for select to authenticated
  using (student_id = (select auth.uid()));

create policy order_feedback_select_staff on public.order_feedback
  for select to authenticated
  using ((select public.has_canteen_role(canteen_id, 'staff')));

revoke all on function public.submit_feedback(uuid, int, text) from public, anon;
grant execute on function public.submit_feedback(uuid, int, text) to authenticated;


-- ===================== 0013_tenancy_auth.sql =====================

-- OAC platform: college_domains is the only source of allowed sign-up domains.
-- The sign-up guard stops reading app_settings, and app_settings (with its admin-writable
-- global row) is dropped. Every other reader moved to canteens/colleges in 0009.

-- ---------------------------------------------------------------------------
-- 1. Re-sync first: a domain set in app_settings after 0008 ran (and never copied into
--    college_domains) would otherwise strand every student of that domain.
-- ---------------------------------------------------------------------------
insert into public.college_domains (domain, college_id)
select s.college_email_domain, c.id
from public.app_settings s
cross join public.colleges c
where c.slug = 'ait-pune'
  and s.college_email_domain is not null
  and s.college_email_domain <> ''
  and not exists (
    select 1 from public.college_domains d where d.domain = s.college_email_domain
  );

-- ---------------------------------------------------------------------------
-- 2. College-email guard on auth.users.
-- Allowed: <local>@<any college_domains.domain>, or app_metadata.provisioned = true.
-- Inserts for the reserved staff login domain are let through here and verified at commit
-- by verify_staff_login_provisioned() (see 0001_schema.sql). An empty college_domains
-- table fails closed.
-- ---------------------------------------------------------------------------
create or replace function public.enforce_college_email()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if coalesce(new.raw_app_meta_data ->> 'provisioned', '') = 'true' then
    return new;
  end if;

  if tg_op = 'INSERT' and new.email ~* '^[^@]+@staff\.oac\.local$' then
    return new;
  end if;

  if new.email is null
     or new.email !~ '^[^@]+@[^@]+$'
     or not exists (
       select 1 from public.college_domains d
       where d.domain = lower(split_part(new.email, '@', 2))
     ) then
    raise exception 'Sign-up is restricted to college email addresses';
  end if;

  return new;
end;
$$;

-- ---------------------------------------------------------------------------
-- 3. app_settings is gone (its policies and grants go with it).
-- ---------------------------------------------------------------------------
drop table public.app_settings;


-- ===================== 0014_security_hardening.sql =====================

-- OAC platform: security hardening from the whole-branch review.

-- ---------------------------------------------------------------------------
-- has_canteen_role: a membership counts only when the canteen is in the member's own college.
-- Memberships are written only with the service-role key, but a stray cross-college row
-- (a bug, or a bad manual fix) must grant nothing. Same signature and attributes as 0008,
-- so every policy, view and RPC that calls it picks this up.
-- ---------------------------------------------------------------------------
create or replace function public.has_canteen_role(p_canteen_id uuid, p_min_role public.canteen_role)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.profiles p
    where p.id = (select auth.uid())
      and p.is_active
      and p.role in ('staff', 'admin')
      and (
        exists (
          select 1
          from public.canteen_members m
          join public.canteens k on k.id = m.canteen_id
          where m.user_id = p.id
            and m.canteen_id = p_canteen_id
            and m.role >= p_min_role
            and k.college_id = p.college_id
        )
        or (
          p.role = 'admin'
          and exists (
            select 1 from public.canteens k
            where k.id = p_canteen_id and k.college_id = p.college_id
          )
        )
      )
  )
$$;

revoke all on function public.has_canteen_role(uuid, public.canteen_role) from public, anon;
grant execute on function public.has_canteen_role(uuid, public.canteen_role) to authenticated;

-- ---------------------------------------------------------------------------
-- A menu item or slot never changes canteen. Row policies alone let an owner of two canteens
-- move rows between them (USING and WITH CHECK both pass), so take away the column itself.
-- The admin console edits menu items with exactly these columns; insert and delete stay.
-- ---------------------------------------------------------------------------
revoke update (canteen_id) on public.slots from authenticated;

revoke update on public.menu_items from authenticated;
grant update (name, description, price_paise, category, is_available, sort, tags, meal_moments)
  on public.menu_items to authenticated;

-- ---------------------------------------------------------------------------
-- The definer views filter on has_canteen_role(); as security barriers, no caller-supplied
-- function or operator in a WHERE clause runs before that filter on rows it would hide.
-- ---------------------------------------------------------------------------
alter view public.staff_orders_v set (security_barrier = true);
alter view public.staff_feedback_v set (security_barrier = true);


