-- ===================== 0016_feedback_summary.sql =====================

-- OAC: the staff feedback page's summary card, computed in SQL.
-- The page used to fetch every rating through PostgREST, which caps a response at 1000 rows, so
-- a busy canteen's count, average and distribution silently stopped growing. This returns one
-- row for the canteen's staff (and owner, and college admin), and zero rows for anyone else.
-- average is rounded to one decimal and null while there is no feedback.

create function public.feedback_summary(p_canteen_id uuid)
returns table (count bigint, average numeric, c1 bigint, c2 bigint, c3 bigint, c4 bigint, c5 bigint)
language sql
stable
security definer
set search_path = ''
as $$
  select
    count(*),
    round(avg(f.rating), 1),
    count(*) filter (where f.rating = 1),
    count(*) filter (where f.rating = 2),
    count(*) filter (where f.rating = 3),
    count(*) filter (where f.rating = 4),
    count(*) filter (where f.rating = 5)
  from public.order_feedback f
  where f.canteen_id = p_canteen_id
  having public.has_canteen_role(p_canteen_id, 'staff')
$$;

revoke all on function public.feedback_summary(uuid) from public, anon;
grant execute on function public.feedback_summary(uuid) to authenticated;


-- ===================== 0017_popular_approved.sql =====================

-- popular_items: students only count approved canteens. A pending or suspended canteen's orders
-- stay visible to its own staff (second branch), but never leak to students through the rpc.
create or replace function public.popular_items(p_canteen_id uuid, p_days int default 30, p_limit int default 8)
returns table (menu_item_id uuid, orders bigint)
language sql
stable
security definer
set search_path = ''
as $$
  select oi.menu_item_id, count(distinct o.id) as orders
  from public.order_items oi
  join public.orders o on o.id = oi.order_id
  join public.menu_items m on m.id = oi.menu_item_id
  join public.canteens c on c.id = m.canteen_id
  where m.canteen_id = p_canteen_id
    and m.is_available
    and o.status not in ('cancelled', 'no_show')
    and o.created_at >= now() - make_interval(days => greatest(1, least(coalesce(p_days, 30), 90)))
    and (select auth.uid()) is not null
    and (
      (c.status = 'approved' and c.college_id = (select public.current_college_id()))
      or (select public.has_canteen_role(p_canteen_id, 'staff'))
    )
  group by oi.menu_item_id, m.name
  order by count(distinct o.id) desc, m.name
  limit greatest(1, least(coalesce(p_limit, 8), 20))
$$;

revoke all on function public.popular_items(uuid, int, int) from public, anon;
grant execute on function public.popular_items(uuid, int, int) to authenticated;


